param(
  [Parameter(Mandatory=$true)][ValidateSet('forge','true-engine','plate')][string]$Project,
  [string]$Root
)
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$projects = @{
  'forge' = @{ Repo='BirthrightPublication/forge'; Label='FORGE' }
  'true-engine' = @{ Repo='BirthrightPublication/True-Engine'; Label='True Engine' }
  'plate' = @{ Repo='BirthrightPublication/License-Plate-Obfuscation'; Label='License Plate Obfuscation Studio' }
}
$p = $projects[$Project]
# Resolve script location without passing a possibly quote-contaminated argument to GetFullPath.
# Root is derived from the .ps1 location unless the caller explicitly supplies a path.
if ([string]::IsNullOrWhiteSpace($Root)) {
  $Root = Split-Path -Parent $MyInvocation.MyCommand.Path
}
$Root = $Root.Trim().Trim('"').TrimEnd([char]92,[char]47)
if ([string]::IsNullOrWhiteSpace($Root) -or -not (Test-Path -LiteralPath $Root -PathType Container)) {
  throw "Invalid application root: [$Root]. Place Update-Application.ps1 in the installed application folder."
}
# Resolve-Path accepts literal paths and returns a filesystem-native absolute path.
$Root = (Resolve-Path -LiteralPath $Root).ProviderPath.TrimEnd([char]92,[char]47)
if ($Root -notmatch '^[A-Za-z]:\\' -and $Root -notmatch '^\\\\') {
  throw "Unexpected filesystem path: [$Root]"
}
$backups = Join-Path $Root 'Update-Backups'
$workspace = Join-Path $env:TEMP ('BirthrightUpdate-' + [guid]::NewGuid().ToString('N'))
$logFolder = Join-Path $Root 'Update-Logs'
New-Item -ItemType Directory -Force $logFolder | Out-Null
$logFile = Join-Path $logFolder ('update-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.log')
function Log([string]$s) { Write-Host $s; Add-Content -LiteralPath $logFile -Value "$(Get-Date -Format s) $s" }
function Inside([string]$relative) {
  if ([IO.Path]::IsPathRooted($relative) -or $relative -match '(^|[\\/])\.{1,2}([\\/]|$)' -or $relative -match '[:*?"<>|]') { throw "Unsafe release path: $relative" }
  $dest = Join-Path $Root $relative
  if (-not $dest.StartsWith($Root + '\', [StringComparison]::OrdinalIgnoreCase)) { throw "Unsafe release path: $relative" }
  return $dest
}
# These are NEVER overwritten by a release package. Extend as needed for your project.
$protectedNames = @('Build','Update-Backups','Update-Logs','Data','data','UserData','user-data','userdata','Settings','settings','Config','config','Presets','presets','Queue','queue','History','history','Logs','logs','Projects','projects','Workspace','workspace','Uploads','uploads','Outputs','outputs','.git','.venv','venv','node_modules','Update FORGE.bat','Update True Engine.bat','Update Plate.bat','Update-Application.ps1')
$protected = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach($n in $protectedNames) { [void]$protected.Add($n) }
function IsProtected([string]$rel) { $parts = $rel -split '[\\/]'; return ($parts | Where-Object { $protected.Contains($_) }).Count -gt 0 }
function CheckLinks([string]$path) {
  $cursor = $path
  while ($cursor.Length -ge $Root.Length -and $cursor.StartsWith($Root,[StringComparison]::OrdinalIgnoreCase)) {
    if (Test-Path -LiteralPath $cursor) {
      $item = Get-Item -LiteralPath $cursor -Force
      if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Refusing to change symbolic link/junction: $cursor" }
    }
    if ($cursor -eq $Root) { break }
    $cursor = Split-Path -Parent $cursor
  }
}
try {
  Log "Starting $($p.Label) update in $Root"
  if (-not (Test-Path -LiteralPath $Root -PathType Container)) { throw 'Installation directory not found.' }
  New-Item -ItemType Directory -Force $workspace | Out-Null
  $headers = @{ 'User-Agent' = 'Birthright-Windows-Updater'; 'Accept' = 'application/vnd.github+json'; 'X-GitHub-Api-Version'='2022-11-28' }
  $api = 'https://api.github.com/repos/' + $p.Repo + '/releases/latest'
  try { $release = Invoke-RestMethod -Uri $api -Headers $headers -TimeoutSec 30 } catch { throw "No accessible published GitHub Release for $($p.Repo). Publish a non-prerelease release with a Windows ZIP asset first. $($_.Exception.Message)" }
  # Explicitly require a Windows application ZIP, not GitHub's autogenerated source archives.
  $assets = @($release.assets | Where-Object { $_.name -match '(?i)(win(dows)?|x64|amd64)' -and $_.name -match '(?i)\.zip$' } | Sort-Object name)
  if ($assets.Count -ne 1) { throw "Expected exactly one Windows ZIP asset in release $($release.tag_name), found $($assets.Count). Name the single asset *-windows-x64.zip." }
  $asset = $assets[0]
  Log "Release $($release.tag_name): $($asset.name)"
  $zip = Join-Path $workspace 'package.zip'
  Invoke-WebRequest -Uri $asset.browser_download_url -OutFile $zip -Headers @{ 'User-Agent'='Birthright-Windows-Updater' } -TimeoutSec 300
  $hash = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant()
  $shaAsset = @($release.assets | Where-Object { $_.name -eq ($asset.name + '.sha256') })
  if ($shaAsset.Count -ne 1) { throw "Missing $($asset.name).sha256 release asset. No files changed." }
  $shaFile = Join-Path $workspace 'package.sha256'
  Invoke-WebRequest -Uri $shaAsset[0].browser_download_url -OutFile $shaFile -Headers @{ 'User-Agent'='Birthright-Windows-Updater' } -TimeoutSec 30
  $expected = ((Get-Content -LiteralPath $shaFile -Raw).Trim() -split '\s+')[0].ToLowerInvariant()
  if ($expected -notmatch '^[a-f0-9]{64}$' -or $hash -ne $expected) { throw 'SHA256 mismatch. Nothing installed.' }
  Log 'SHA256 verified against release checksum file.'
  $extract = Join-Path $workspace 'extracted'
  Expand-Archive -LiteralPath $zip -DestinationPath $extract -Force
  # Contract: archive must contain app/ at its root. No other root contents are installed.
  $source = Join-Path $extract 'app'
  if (-not (Test-Path -LiteralPath $source -PathType Container)) { throw 'Release ZIP must contain an app/ directory at archive root. Nothing installed.' }
  $files = @(Get-ChildItem -LiteralPath $source -Recurse -File -Force)
  if ($files.Count -eq 0) { throw 'No application files in app/.' }
  if (@(Get-ChildItem -LiteralPath $source -Recurse -Force -Attributes ReparsePoint).Count -gt 0) { throw 'Links in release ZIP are not permitted.' }
  $changes = @()
  foreach($f in $files) {
    $rel = $f.FullName.Substring($source.Length).TrimStart('\','/')
    if (IsProtected $rel) { throw "Release attempts to overwrite protected path: $rel" }
    $dest = Inside $rel
    CheckLinks $dest
    if (Test-Path -LiteralPath $dest -PathType Container) { throw "Destination is a folder: $dest" }
    $changes += [pscustomobject]@{ src=$f.FullName; dest=$dest; rel=$rel; existed=(Test-Path -LiteralPath $dest -PathType Leaf) }
  }
  Log "Prepared $($changes.Count) application files. Close the application before continuing."
  $response = Read-Host 'Type UPDATE to back up and install this release (anything else cancels)'
  if ($response -cne 'UPDATE') { Log 'Cancelled. No files modified.'; exit 0 }
  $backup = Join-Path $backups ((Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + $release.tag_name)
  New-Item -ItemType Directory -Force $backup | Out-Null
  # Preserve overwritten files first, and record all newly added paths for rollback.
  $manifest = @()
  foreach($c in $changes) {
    if ($c.existed) {
      $b = Join-Path $backup $c.rel
      New-Item -ItemType Directory -Force (Split-Path $b -Parent) | Out-Null
      Copy-Item -LiteralPath $c.dest -Destination $b -Force
    }
    $manifest += [pscustomobject]@{path=$c.rel;existed=$c.existed}
  }
  $manifest | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $backup 'rollback-manifest.json') -Encoding UTF8
  $applied = [Collections.Generic.List[object]]::new()
  try {
    foreach($c in $changes) {
      New-Item -ItemType Directory -Force (Split-Path $c.dest -Parent) | Out-Null
      $applied.Add($c)
      Copy-Item -LiteralPath $c.src -Destination $c.dest -Force
    }
  } catch {
    Log "Installation failed. Reverting $($applied.Count) modified files."
    foreach($c in $applied) {
      if ($c.existed) { Copy-Item -LiteralPath (Join-Path $backup $c.rel) -Destination $c.dest -Force }
      else { Remove-Item -LiteralPath $c.dest -Force -ErrorAction SilentlyContinue }
    }
    throw
  }
  Log "SUCCESS: Updated $($p.Label) to $($release.tag_name). Backup: $backup"
  Log 'Unchanged files are left in place; no migration or application health check was performed.'
} catch {
  Log "ERROR: $($_.Exception.Message)"
  exit 1
} finally {
  Remove-Item -LiteralPath $workspace -Recurse -Force -ErrorAction SilentlyContinue
}
